import { Component, h, Prop, Event, EventEmitter, Element, State, Host, Listen, Watch } from '@stencil/core';
import classnames from 'classnames';
import { Status } from '@src/shared/base-props';
import { RadioValue } from './types';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { Consume } from '@src/framework/runtime-context/decorators/consume';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { RadioGroupContext } from './context';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { KsIconHelp } from '@fe-infra/keystone-icons-stencil';

const prefix = 'radio';

/**
 * @slot default - The slot for the main radio label content.
 * @slot prefix - The slot for the prefix.
 * @slot suffix - The slot for the suffix.
 * @slot description - The slot for providing descriptive text for the radio. Appears under the radio label.
 * @slot descriptionBelow - The slot for providing long descriptive text for the radio. Appears under the whole radio.
 * @slot helpContent - The slot for the help content inside the tooltip icon.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-radio',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsRadio extends FormBaseComponent<boolean> {
  static vModel = { prop: 'checked', event: 'ksChange' };
  @Element() el!: HTMLKsRadioElement;

  @Consume({
    context: RadioGroupContext,
    subscribe: true,
    path: ['htmlName'],
  })
  @State()
  nameFromRadioGroup!: string;
  @Consume({
    context: RadioGroupContext,
    subscribe: true,
    path: ['value'],
  })
  @State()
  valueFromRadioGroup?: RadioValue;
  @Consume({
    context: RadioGroupContext,
    subscribe: true,
    path: ['disabled'],
  })
  @State()
  disabledFromRadioGroup?: boolean;
  @Consume({
    context: RadioGroupContext,
    path: ['onValueChange'],
  })
  private onValueChangeFromRadioGroup?: (value: RadioValue) => void;

  /** Indicates whether the radio button is disabled. When `true`, the radio button will be inactive and unselectable. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The status of the radio. Can be one of the following values: `success`, `error`, `warning`, `default`. */
  @Prop() @FormContextValueReconcile() status?: Status;
  /** Indicates whether the radio button is currently checked. When true, the radio button will be selected. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) checked?: boolean;
  /** Set the initial checked state of the radio when the component is first rendered. This does not change after the initial render. */
  @Prop() defaultChecked?: boolean;
  @Uncontrollable('checked', 'defaultChecked', 'ksChange') @State() internalCheckedState?: boolean;
  /** Whether the radio should receive focus on render. */
  @Prop() autoFocus?: boolean;
  /** size of radio. Only 'md' is supported. */
  @Prop() size = 'md' as const;
  /** The value associated with the radio button. This is the data that will be returned when the radio button is checked. It is used to identify the radio button in the context of the form or group. */
  @Prop() @Vue2ValueFix() value?: RadioValue;
  /** Whether to force the radio to ignore the KsRadioGroup management. If set to `true`, the radio's checked state can be independently controlled, even if it is nested within a KsRadioGroup. */
  @Prop() forceIgnoreGroup = false;
  /** Custom event triggered when the checked state of the radio button changes. This event can be used to execute additional actions upon selection change. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<boolean>;
  @Listen('ksChange')
  onKsChange(event: CustomEvent<boolean>) {
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: event.detail } });

    this.onValueChangeFromRadioGroup?.(this.value || '');

    // FIXME: stencil extend does not support 2 listener on same event
    this.onKsChangeForForm(event);
  }
  /** The default slot for the label of the radio. */
  @Slot({ slotname: '_default' }) private defaultSlot?: Slots;
  /** The slot for the prefix of the radio. */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;
  /** The slot for the suffix of the radio. */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;
  /** The slot for the description of the radio. */
  @Slot({ slotname: 'description' }) private descriptionSlots?: Slots;
  /** The slot for the description of the checkbox. */
  @Slot({ slotname: 'descriptionBelow' }) private descriptionBelowSlots?: Slots;
  /** The slot for the help content inside the tooltip icon */
  @Slot({ slotname: 'helpContent' }) private helpContentSlot?: Slots;

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  get resolvedDisabled() {
    return (!this.forceIgnoreGroup && this.disabledFromRadioGroup) || this.disabled;
  }

  @Watch('valueFromRadioGroup')
  handleValueFromRadioGroupChange() {
    const checked =
      this.valueFromRadioGroup !== undefined && !this.forceIgnoreGroup
        ? this.valueFromRadioGroup === this.value
        : this.internalCheckedState;
    this.checked = checked;
  }

  private handleValueChange = (event: Event) => {
    if (this.resolvedDisabled) {
      return;
    }
    const value = (event.target as HTMLInputElement).checked;
    this.internalCheckedState = value;
  };

  private stopPropagation(event: Event) {
    event.stopPropagation();
  }

  private get hasDefaultSlotContent() {
    return (
      Boolean(this.defaultSlot?.length) ||
      Array.from(this.el.childNodes).some(
        (node) => node.nodeType === Node.TEXT_NODE && Boolean(node.textContent?.trim()),
      )
    );
  }

  render() {
    const displayClassPrefix = `${prefix}__display`;
    const hasContent = this.hasDefaultSlotContent || this.descriptionSlots || this.helpContentSlot || this.suffixSlot;
    const classes = classnames(`${prefix}`, `${prefix}--size-${this.size}`, {
      [`${prefix}--disabled`]: this.resolvedDisabled,
      [`${prefix}--checked`]: this.internalCheckedState,
      [`${prefix}--${this.status}`]: this.status,
      [`${prefix}--start`]: this.descriptionSlots,
    });
    return (
      <Host class="KsRadio" role="radio">
        <div class={classes} part="base">
          <div class={`${prefix}__control`}>
            <input
              id="radio"
              onChange={this.handleValueChange}
              class={displayClassPrefix}
              type="radio"
              name={this.nameFromRadioGroup}
              disabled={this.resolvedDisabled}
              autoFocus={this.autoFocus}
              checked={this.internalCheckedState}
              data-testid="ks-radio-index-8AA75q"
            />
            {this.prefixSlot && <slot name="prefix" />}
          </div>

          {hasContent && (
            <div class={`${prefix}__content`}>
              <div class={`${prefix}__content__header`}>
                <label
                  class={`${prefix}__label`}
                  htmlFor="radio"
                  onClick={this.stopPropagation}
                  data-testid="ks-radio-index-3WaLsv"
                >
                  <slot />
                </label>
                {this.helpContentSlot && (
                  <ks-tooltip size={this.size}>
                    <KsIconHelp style={{ color: 'var(--ks-color-neutral-lowOnSurface)' }} />
                    <slot name="helpContent" slot="content" />
                  </ks-tooltip>
                )}
                {this.suffixSlot && <slot name="suffix" />}
              </div>
              {this.descriptionSlots && (
                <div class={`${prefix}__description`}>
                  <slot name="description" />
                </div>
              )}
            </div>
          )}
        </div>
        {this.descriptionBelowSlots && (
          <div class={classnames(`${prefix}__description`, `${prefix}__description--below`)}>
            <slot name="descriptionBelow" />
          </div>
        )}
      </Host>
    );
  }

  componentWillLoad() {
    this.handleValueFromRadioGroupChange();
  }
}
